// Generated by valid telemetry, never by public dashboard reads. The unique UTC
// day is an atomic publication lock: racing collectors cannot replace a snapshot.
export const SNAPSHOT_SQL = `INSERT OR IGNORE INTO public_activity(day, payload)
 SELECT ?1, (
 WITH visits AS MATERIALIZED (
   SELECT device, MIN(running, ?1 - started) AS running,
     MIN(advancing, running, ?1 - started) AS advancing
   FROM sessions WHERE started >= ?1 - 90 * 86400 AND started < ?1
 ), ordered AS (SELECT running FROM visits ORDER BY running),
 totals AS (SELECT COUNT(*) AS sessions, COALESCE(SUM(running),0) AS running,
   COALESCE(SUM(advancing),0) AS advancing, COALESCE(AVG(running),0) AS average,
   COALESCE(MAX(running),0) AS longest, COALESCE(SUM(running >= 300),0) AS over5,
   COALESCE(SUM(running >= 900),0) AS over15, COALESCE(SUM(running >= 1800),0) AS over30 FROM visits),
 median AS (SELECT COALESCE(AVG(running),0) AS value FROM
   (SELECT running FROM ordered LIMIT 2 - (SELECT COUNT(*) FROM visits) % 2
     OFFSET MAX(0, ((SELECT COUNT(*) FROM visits) - 1) / 2))),
 devices AS (SELECT device AS name, COUNT(*) AS sessions FROM visits GROUP BY device ORDER BY device)
 SELECT json_object('days',90,'totals',json_object(
   'sessions',t.sessions,'running',t.running,'advancing',t.advancing,'average',t.average,
   'median',m.value,'longest',t.longest,'over5',t.over5,'over15',t.over15,'over30',t.over30),
   'devices',json((SELECT json_group_array(json_object('name',name,'sessions',sessions)) FROM devices)))
 FROM totals t, median m)
 WHERE NOT EXISTS (SELECT 1 FROM public_activity WHERE day = ?1)`;
export const SNAPSHOT_READ_SQL = 'SELECT payload FROM public_activity WHERE day = ?1';
export const SNAPSHOT_PURGE_SQL = 'DELETE FROM public_activity WHERE day < ?1';

export function publishActivity(env, now) {
  const day = Math.floor(now / 86400) * 86400;
  return env.GARDEN_STATS.prepare(SNAPSHOT_SQL).bind(day).run();
}

// Site-wide counters, not visitor/IP tracking. Two fixed rows bound storage and
// atomic UPSERTs enforce the budget even when requests arrive concurrently.
export const ADMISSION_SQL = `INSERT INTO analytics_limits(name, window, hits) VALUES (?1, ?2, 1)
 ON CONFLICT(name) DO UPDATE SET window = excluded.window,
 hits = CASE WHEN analytics_limits.window < excluded.window THEN 1 ELSE analytics_limits.hits + 1 END
 WHERE analytics_limits.window < excluded.window OR
 (analytics_limits.window = excluded.window AND analytics_limits.hits < ?3)
 RETURNING hits`;
export async function admitted(env, kind, now) {
  return Boolean(await env.GARDEN_STATS.prepare(ADMISSION_SQL)
    .bind(kind, Math.floor(now / 60), kind === 'starts' ? 120 : 6000).first());
}
